package io.github.mighil31.kitchensink.member;

import org.bson.types.ObjectId;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

/**
 * A registered member, stored in the {@code members} collection.
 *
 * <p>No {@code @Indexed} annotations: index creation at startup is off, and the indexes are
 * versioned migrations in {@code io.github.mighil31.kitchensink.migration} (ADR 0005).
 *
 * @param id generated by the driver on insert (ADR 0002)
 * @param legacyId the JBoss app's numeric id, only on members carried over from it; null fields
 *     are not written, which is what the partial unique index on {@code legacyId} relies on
 */
@Document(Member.COLLECTION)
public record Member(@Id ObjectId id, String name, String email, String phoneNumber, Long legacyId) {

    public static final String COLLECTION = "members";

    /** A new member, without an id yet. */
    public static Member of(String name, String email, String phoneNumber) {
        return new Member(null, name, email, phoneNumber, null);
    }

    public Member withId(ObjectId id) {
        return new Member(id, name, email, phoneNumber, legacyId);
    }
}
